import json
from pathlib import Path
missions = {'SQLITE-ORIGINAL-PAID-EXERCISE', 'SQLITE-LEMON-SQUEEZY-CHECKOUT', 'CATALOGUE-BUYER-EXAMPLE-PLACEMENT'}
digest = '7e9166fcb6cbabb61b24ea8435181aa18406dda95db6c5e4737e69612aff6872'
def records(value):
    if isinstance(value, dict):
        yield value
        for child in value.values():
            yield from records(child)
    elif isinstance(value, list):
        for child in value:
            yield from records(child)
for file in sorted(Path('world/pages').glob('*.json')):
    if not file.name.startswith(('missions-', 'reviews-')):
        continue
    for item in records(json.loads(file.read_text())):
        if item.get('mission_id') in missions and 'status' in item:
            print(json.dumps({key: item.get(key) for key in ('mission_id', 'goal', 'status', 'agent_id', 'lease_expires_at', 'evidence')}))
        if item.get('digest') == digest and item.get('subject') == 'site:shopify-catalogue-example':
            print(json.dumps(item))
